// Simple endless runner targeting canvas with id="game"
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth;
canvas.height = canvas.clientHeight;

// Game config
const GRAVITY = 0.6;
const JUMP = -12;
const PLAYER_W = 30;
const PLAYER_H = 50;
const OBSTACLE_W = 30;
const OBSTACLE_GAP = 200; // distance between obstacles
const SPEED = 4;

let player = {x: 50, y: canvas.height - PLAYER_H, w: PLAYER_W, h: PLAYER_H, vy: 0, onGround: true};
let obstacles = [];
let frames = 0;
let score = 0;
let gameOver = false;

input.oldString:
// player
  ctx.fillStyle = '#0a84ff';
  ctx.fillRect(player.x, player.y, player.w, player.h);

input.newString:
// player - draw rounded rectangle with gradient fill
  const playerGrad = ctx.createLinearGradient(0, player.y, 0, player.y + player.h);
  playerGrad.addColorStop(0, '#4A90E2');
  playerGrad.addColorStop(1, '#0A84FF');
  ctx.fillStyle = playerGrad;
  ctx.beginPath();
  ctx.moveTo(player.x + 5, player.y);
  ctx.lineTo(player.x + player.w - 5, player.y);
  ctx.quadraticCurveTo(player.x + player.w, player.y, player.x + player.w, player.y + 5);
  ctx.lineTo(player.x + player.w, player.y + player.h - 5);
  ctx.quadraticCurveTo(player.x + player.w, player.y + player.h, player.x + player.w - 5, player.y + player.h);
  ctx.lineTo(player.x + 5, player.y + player.h);
  ctx.quadraticCurveTo(player.x, player.y + player.h, player.x, player.y + player.h - 5);
  ctx.lineTo(player.x, player.y + 5);
  ctx.quadraticCurveTo(player.x, player.y, player.x + 5, player.y);
  ctx.closePath();
  ctx.fill();

